import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: interFamily } = loadInter();



export type LiquidNotificationProps = Record<string, any>;

const LiquidNotification: React.FC<LiquidNotificationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  message = "Get Charles Matcha 🍵",
  appName = "REMINDERS",
  timeText = "now",
  cardOpacity = 0.55,
  blurAmount = 45,
  theme = "dark",
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const isDark = theme === "dark";
  const durationFrames = durationInSeconds * fps;

  // Colors based on theme
  const cardBg = isDark ? `rgba(35, 35, 35, ${cardOpacity})` : `rgba(255, 255, 255, ${cardOpacity})`;
  const borderColor = isDark ? `rgba(255, 255, 255, 0.15)` : `rgba(0, 0, 0, 0.08)`;
  const innerHighlight = isDark ? `rgba(255, 255, 255, 0.1)` : `rgba(255, 255, 255, 0.6)`;
  const textColor = isDark ? "#FFFFFF" : "#000000";
  const mutedTextColor = isDark ? "rgba(255, 255, 255, 0.5)" : "rgba(0, 0, 0, 0.5)";

  // Intro Animation
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 120, mass: 0.8 },
  });

  const entranceOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Outro Animation
  const outroStart = durationFrames - fps; // Start exiting 1 second before end
  const outroProgress = interpolate(frame, [outroStart, durationFrames], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const outroSpring = spring({
    frame: frame - outroStart,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // Combined Transforms
  const scaleIn = interpolate(entranceSpring, [0, 1], [0.85, 1]);
  const scaleOut = interpolate(outroProgress, [0, 1], [1, 0.95]);
  const finalScale = scaleIn * scaleOut;

  const yIn = interpolate(entranceSpring, [0, 1], [120, 0]);
  const yOut = interpolate(outroSpring, [0, 1], [0, -60]);
  const finalY = yIn + yOut;

  const outroOpacity = interpolate(frame, [outroStart, durationFrames - 15], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const finalOpacity = entranceOpacity * outroOpacity;

  // Responsive width sizing
  const cardWidth = Math.min(width * 0.6, 850);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          width: cardWidth,
          position: "relative",
          display: "flex",
          flexDirection: "column",
          padding: "32px 36px",
          borderRadius: "44px",
          backgroundColor: cardBg,
          backdropFilter: `blur(${blurAmount}px)`,
          WebkitBackdropFilter: `blur(${blurAmount}px)`,
          border: `1.5px solid ${borderColor}`,
          boxShadow: `0 32px 64px rgba(0,0,0,${isDark ? 0.4 : 0.15})`,
          transform: `translateY(${finalY}px) scale(${finalScale})`,
          opacity: finalOpacity,
          transition: "none",
          overflow: "hidden", // for the inner highlight
        }}
      >
        {/* Inner Glass Highlight (Top Rim Light) */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            height: "50%",
            background: `linear-gradient(to bottom, ${innerHighlight}, transparent)`,
            opacity: 0.5,
            pointerEvents: "none",
            transition: "none",
          }}
        />

        {/* Header Section */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            marginBottom: "28px",
            zIndex: 1,
            transition: "none",
          }}
        >
          {/* App Icon (Simulated Reminders Icon) */}
          <div
            style={{
              width: "36px",
              height: "36px",
              borderRadius: "10px",
              backgroundColor: "#FFFFFF",
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              alignItems: "center",
              gap: "4px",
              boxShadow: "0 2px 8px rgba(0,0,0,0.2)",
              transition: "none",
              marginRight: "16px",
            }}
          >
            <div style={{ display: "flex", gap: "3px", transition: "none" }}>
              <div style={{ width: "4px", height: "4px", borderRadius: "2px", backgroundColor: "#FF3B30", transition: "none" }} />
              <div style={{ width: "12px", height: "4px", borderRadius: "2px", backgroundColor: "#E5E5EA", transition: "none" }} />
            </div>
            <div style={{ display: "flex", gap: "3px", transition: "none" }}>
              <div style={{ width: "4px", height: "4px", borderRadius: "2px", backgroundColor: "#FF9500", transition: "none" }} />
              <div style={{ width: "12px", height: "4px", borderRadius: "2px", backgroundColor: "#E5E5EA", transition: "none" }} />
            </div>
            <div style={{ display: "flex", gap: "3px", transition: "none" }}>
              <div style={{ width: "4px", height: "4px", borderRadius: "2px", backgroundColor: "#007AFF", transition: "none" }} />
              <div style={{ width: "12px", height: "4px", borderRadius: "2px", backgroundColor: "#E5E5EA", transition: "none" }} />
            </div>
          </div>

          <span
            style={{
              fontSize: "20px",
              fontWeight: 500,
              letterSpacing: "0.05em",
              color: mutedTextColor,
              textTransform: "uppercase",
              transition: "none",
            }}
          >
            {appName}
          </span>

          <span
            style={{
              marginLeft: "auto",
              fontSize: "20px",
              fontWeight: 400,
              color: mutedTextColor,
              transition: "none",
            }}
          >
            {timeText}
          </span>
        </div>

        {/* Content Section */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "flex-start",
            zIndex: 1,
            transition: "none",
          }}
        >
          {/* Action / Checkbox Circle */}
          <div
            style={{
              width: "48px",
              height: "48px",
              borderRadius: "50%",
              border: `2.5px solid ${mutedTextColor}`,
              flexShrink: 0,
              marginRight: "24px",
              marginTop: "2px",
              transition: "none",
            }}
          />

          {/* Message Text */}
          <span
            style={{
              fontSize: "36px",
              lineHeight: 1.3,
              fontWeight: 600,
              color: textColor,
              textShadow: isDark ? "0 2px 4px rgba(0,0,0,0.3)" : "none",
              transition: "none",
            }}
          >
            {message}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LiquidNotification;